def verdict(source, version):
    try:
        ast.parse(source, "<case>", feature_version=(3, version))
        compile(source, "<case>", "exec", dont_inherit=True)
        return "valid"
    except (SyntaxError, ValueError, MemoryError, RecursionError, UnicodeError) as e:
        return "%s: %s" % (type(e).__name__, getattr(e, "msg", None) or str(e))


assert sys.version_info[:2] == (3, 14), sys.version
names = set()
with open(sys.argv[1], "w", encoding="utf-8", newline="\n") as out:
    for case in CASES:
        name, source = case[0], case[1]
        version = case[2] if len(case) > 2 else 14
        assert name not in names, name
        names.add(name)
        out.write(json.dumps({"name": name, "version": version, "source": source, "want": verdict(source, version)}) + "\n")
print(len(CASES), "cases")
